from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class SimpleParameter(SchemaObject):
    name = SchemaField(name='name', optional=True)
    full_name = SchemaField(name='full_name', optional=True)
    state = SchemaField(name='state', optional=True)
    value = SchemaField(name='value', optional=True)

    def __init__(self, name, full_name, state, value):
        self.name = name
        self.full_name = full_name
        self.state = state
        self.value = value

        super(SimpleParameter, self).__init__()


class SimpleListParameter(SchemaObject):
    name = SchemaField(name='name', optional=True)
    full_name = SchemaField(name='full_name', optional=True)
    state = SchemaField(name='state', optional=True)
    value = SchemaField(name='value', many=True, optional=True)

    def __init__(self, name, full_name, state, value):
        self.name = name
        self.full_name = full_name
        self.state = state
        self.value = value

        super(SimpleListParameter, self).__init__()


class ComplexParameter(SchemaObject):
    name = SchemaField(name='name', optional=True)
    full_name = SchemaField(name='full_name', optional=True)
    state = SchemaField(name='state', optional=True)
    value = SchemaField(name='value', many=True, optional=True)

    def __init__(self, name, full_name, state, value):
        self.name = name
        self.full_name = full_name
        self.state = state
        self.value = value

        super(ComplexParameter, self).__init__()


class ParameterContainer(SchemaObject):
    parameter_type = SchemaField(name='parameter_type', not_null=True)
    simple_parameter = SchemaField(name='simple_parameter', optional=True, klass=SimpleParameter)
    simple_list_parameter = SchemaField(name='simple_list_parameter', klass=SimpleListParameter, optional=True)
    complex_parameter = SchemaField(name='complex_parameter', klass=ComplexParameter, optional=True)

    def __init__(self, parameter_type, simple_parameter, simple_list_parameter, complex_parameter):
        self.parameter_type = parameter_type
        self.simple_parameter = simple_parameter
        self.simple_list_parameter = simple_list_parameter
        self.complex_parameter = complex_parameter

        super(ParameterContainer, self).__init__()


class ManagedObjectParameters(SchemaObject):
    nidd_id = SchemaField(name='nidd_id', not_null=True)
    parameters = SchemaField(name='parameters', not_null=True, many=True, klass=ParameterContainer)

    def __init__(self, nidd_id, parameters):
        self.nidd_id = nidd_id
        self.parameters = parameters

        super(ManagedObjectParameters, self).__init__()
